AULAS[77] = { ill:'quebracabeca', slides:[
  {type:'capa', title:'Conjunções', sub:'Palavras que ligam ideias'},
  {type:'objetivos', items:['Reconhecer conjunções','Identificar o sentido de cada conjunção','Usar conjunções para ligar orações','Melhorar a coesão dos textos']},
  {type:'pergunta', q:'"Choveu. O jogo continuou." Que palavra pode ligar essas frases?', hint:'A segunda ideia é o que se esperava?', ill:'balao'},
  {type:'conceito', title:'Conectar ideias', text:'**Conjunções** ligam palavras e orações e mostram a **relação de sentido** entre elas: adição, oposição, causa, tempo, condição, finalidade.', box:'Choveu, mas o jogo continuou. (oposição)', ill:'quebracabeca'},
  {type:'exemplos', title:'Sentidos das conjunções', cards:[['Adição','e, nem: Estudei e passei.'],['Oposição','mas, porém: Estudei, mas não passei.'],['Causa','porque, pois: Faltei porque adoeci.'],['Condição','se: Se chover, ficaremos em casa.']]},
  {type:'exemplos', title:'Mais sentidos', cards:[['Tempo','quando: Quando cheguei, todos saíram.'],['Finalidade','para que: Estudo para que aprenda.'],['Conclusão','portanto, então: Choveu; portanto, molhou.'],['Comparação','como: Corre como um raio.']]},
  {type:'texto', title:'Leitura: o passeio adiado', text:'Íamos ao zoológico no sábado, mas choveu muito. Ficamos em casa porque as estradas estavam alagadas. Se o tempo melhorar, iremos na próxima semana. Quando a chuva passou, jogamos um jogo de tabuleiro.', source:'Texto criado para esta aula', side:{h:'Identifique o sentido', items:['MAS','PORQUE','SE e QUANDO']}},
  {type:'passos', title:'Como escolher', steps:[['Leia as ideias','Separadamente'],['Pense na relação','Soma? Oposição? Causa?'],['Escolha','A conjunção certa'],['Releia','O sentido ficou claro?']]},
  {type:'mapa', title:'Mapa mental', center:'CONJUNÇÕES', nodes:[['Adição','e, nem'],['Oposição','mas, porém'],['Causa','porque, pois'],['Condição','se, caso'],['Tempo','quando'],['Finalidade','para que']]},
  {type:'atividade', title:'Atividade 1: ligue as ideias', instr:'Una as frases com uma conjunção adequada.', items:[{q:'Estava frio. Saí sem casaco.', r:'Estava frio, mas saí sem casaco.'},{q:'Fiquei feliz. Ganhei um presente.', r:'Fiquei feliz porque ganhei um presente.'},{q:'Você estudar. Você vai aprender.', r:'Se você estudar, vai aprender.'}]},
  {type:'atividade', title:'Atividade 2: qual sentido?', instr:'Escreva o sentido da conjunção destacada.', items:[{q:'Saí cedo PARA QUE não me atrasasse.', r:'Finalidade'},{q:'QUANDO o sinal tocou, saímos.', r:'Tempo'},{q:'Ele não estudou NEM fez a lição.', r:'Adição (negativa)'}]},
  {type:'quiz', q:'"Queria ir, MAS estava doente." MAS indica...', opts:['adição','oposição','tempo','finalidade'], c:1, why:'Contraria a expectativa.'},
  {type:'quiz', q:'"Se fizer sol, iremos à praia." SE indica...', opts:['condição','causa','conclusão','adição'], c:0, why:'Depende de uma condição.'},
  {type:'quiz', q:'Qual conjunção indica causa?', opts:['quando','porque','mas','e'], c:1, why:'PORQUE introduz a causa.'},
  {type:'gabarito'},
  {type:'resumo', items:['Conjunções ligam ideias.','Cada uma expressa um sentido.','Escolher bem melhora a coesão.','Mudar a conjunção muda o sentido.']},
  {type:'auto', items:['Reconheço conjunções.','Identifico o sentido de cada uma.','Uso conjunções nos meus textos.','Ligo orações com coerência.']},
  {type:'encerramento', casa:'Escreva 4 frases sobre o seu dia usando: mas, porque, quando e se.'}
]};

