AULAS[82] = { ill:'balao', slides:[
  {type:'capa', title:'Piadas, anedotas e cartuns', sub:'O humor nos textos'},
  {type:'objetivos', items:['Reconhecer piadas, anedotas e cartuns','Identificar o que provoca o humor','Perceber o duplo sentido','Registrar uma piada respeitosa']},
  {type:'pergunta', q:'Por que uma piada tem graça?', hint:'Pense na surpresa do final.', ill:'balao'},
  {type:'conceito', title:'Textos de humor', text:'**Piadas** e **anedotas** são narrativas curtas que terminam com um **desfecho surpreendente**. O **cartum** faz humor com uma **imagem**, às vezes com crítica.', box:'O humor nasce da quebra de expectativa e do duplo sentido.', ill:'balao'},
  {type:'exemplos', title:'Recursos de humor', cards:[['Duplo sentido','Uma palavra com dois significados'],['Exagero','Situações absurdas'],['Surpresa','Final inesperado'],['Imagem','Expressões e detalhes no cartum']]},
  {type:'texto', title:'Leitura: piada', text:'A professora pergunta:\n— Joãozinho, o que é um ponto?\n— Um pingo que parou de cair, professora.\n\nO cliente pergunta ao garçom:\n— Tem sopa de tartaruga?\n— Tem, mas demora um pouquinho para chegar.', source:'Piadas populares adaptadas', side:{h:'Analise', items:['Onde está a surpresa?','Que ideia sobre a tartaruga gera humor?','Que palavra tem duplo sentido?']}},
  {type:'comparacao', title:'Piada x cartum', left:{h:'Piada', items:['Texto verbal','Pode ser contada oralmente','Final surpreendente']}, right:{h:'Cartum', items:['Imagem (com ou sem texto)','Um só quadro','Muitas vezes faz crítica']}},
  {type:'exemplos', title:'Humor respeitoso', cards:[['Rir com','Todos se divertem'],['Não rir de','Características de pessoas'],['Evitar','Preconceitos e ofensas'],['Preferir','Jogos de palavras e situações']]},
  {type:'mapa', title:'Mapa mental', center:'HUMOR', nodes:[['Piada','Narrativa curta'],['Anedota','Caso engraçado'],['Cartum','Imagem crítica'],['Surpresa','Final inesperado'],['Duplo sentido','Ambiguidade'],['Respeito','Sem ofensas']]},
  {type:'atividade', title:'Atividade 1: explique o humor', instr:'Explique por que a piada tem graça.', items:[{q:'A piada do ponto', r:'Brinca com a ideia de que o ponto parece uma gota parada'},{q:'A piada da tartaruga', r:'A tartaruga é lenta, então a sopa "demora para chegar"'}]},
  {type:'desafio', title:'Desafio: livro de piadas da turma', text:'Registre uma piada respeitosa que você conhece.', items:['Escreva com diálogo e travessão','Mantenha o final surpreendente','Evite piadas que ofendam pessoas','Ilustre como um cartum'], ill:'lapis'},
  {type:'quiz', q:'O que geralmente provoca humor numa piada?', opts:['Um final previsível','Um final surpreendente','Muitas datas','Uma lista de ingredientes'], c:1, why:'A quebra de expectativa gera riso.'},
  {type:'quiz', q:'O cartum é...', opts:['um texto longo','uma imagem humorística, muitas vezes crítica','uma receita','um verbete'], c:1, why:'Usa imagem para fazer humor.'},
  {type:'quiz', q:'Humor respeitoso é aquele que...', opts:['ofende alguém','não ridiculariza pessoas','usa preconceitos','humilha'], c:1, why:'Todos podem rir juntos.'},
  {type:'gabarito'},
  {type:'resumo', items:['Piadas têm final surpreendente.','Cartuns fazem humor com imagens.','Duplo sentido e exagero geram riso.','Humor deve respeitar as pessoas.']},
  {type:'auto', items:['Reconheço textos de humor.','Explico o que provoca o riso.','Percebo o duplo sentido.','Escolho piadas respeitosas.']},
  {type:'encerramento', casa:'Pergunte a alguém da família uma piada e registre-a por escrito.'}
]};

